def flip_index(M, k):
    return (_sage_const_2  ** M - _sage_const_1 ) - k


def even_sector_basis(M):
    """F^{(+)} ∩ R^{2^M} の正規直交基底（実）。"""
    d = _sage_const_2  ** M
    cols = []
    for k in range(d):
        kb = flip_index(M, k)
        if k < kb:
            v = vector(RDF, d)
            v[k] = _sage_const_1  / sqrt(RDF(_sage_const_2 )); v[kb] = _sage_const_1  / sqrt(RDF(_sage_const_2 ))
            cols.append(v)
    return matrix(RDF, cols).transpose()


def top_eig(A):
    return max([RDF(CDF(z).real()) for z in A.eigenvalues()])


def to_real(A):
    return matrix(RDF, [[A[i, j].real() for j in range(A.ncols())] for i in range(A.nrows())])


def test_vectors(M, Wr):
    """Step 3 の x の例: 乱数（符号の混じった成分）、W の最大固有ベクトル、F^{(-)} 側の実ベクトル。"""
    d = _sage_const_2  ** M
    xs = []
    for _ in range(_sage_const_6 ):
        x = vector(RDF, [RDF.random_element(-_sage_const_1 , _sage_const_1 ) for _ in range(d)])
        xs.append(x / x.norm())
    import numpy as np
    w, V = np.linalg.eigh(np.array([[float(Wr[i, j]) for j in range(d)] for i in range(d)]))
    x = vector(RDF, [RDF(t) for t in V[:, int(np.argmax(w))]])
    xs.append(x / x.norm())
    y = vector(RDF, d)
    y[_sage_const_0 ] = _sage_const_1 ; y[flip_index(M, _sage_const_0 )] = -_sage_const_1    # ε y = −y（奇セクター側の実ベクトル。u = |y| は偶セクターへ移る）
    xs.append(y / y.norm())
    return xs


REL = _sage_const_1en12    # 不等式の判定の相対余裕（倍精度の丸め分）。等式は TOL で判定する。
w_step2 = w_lower = _sage_const_0 
w_sand = _sage_const_0 
