# (4) 熱力学極限
print("  --- (1/M) log Λ^{(δ)}_M の M → ∞ 収束（Onsager 積分と比較） ---")


def onsager_limit(P):
    """(1/2)log(2 sinh 2K_2) + (1/4π)∫_0^{2π} arccosh(γ_1(θ)) dθ"""
    f = lambda t: RDF(arccosh(g1(RDF(t), P)))
    val = numerical_integral(f, _sage_const_0 , float(_sage_const_2  * pi), max_points=_sage_const_20000 )[_sage_const_0 ]
    return RDF(log(_sage_const_2  * P['s2']) / _sage_const_2  + RDF(val) / (_sage_const_4  * pi))


w_lim = _sage_const_0 
for p in [EIG_PARAMS[_sage_const_1 ], EIG_PARAMS[_sage_const_3 ], EIG_PARAMS[_sage_const_4 ]]:
    P = coeffs(p['K1'], p['K2'])
    target = onsager_limit(P)
    row = []
    for M in [_sage_const_4 , _sage_const_16 , _sage_const_64 , _sage_const_256 , _sage_const_1024 , _sage_const_4096 ]:
        lh = log_Lambda_delta_over_M(M, P, RDF(_sage_const_1 ) / _sage_const_2 )
        lz = log_Lambda_delta_over_M(M, P, RDF(_sage_const_0 ))
